"""Independently validate the four-task Colab runner summary."""
from __future__ import annotations
import argparse,hashlib,json
from pathlib import Path
EXPECTED={"scripts/run_real_peripheral_agent_repair.py","scripts/run_real_operation_partition_agent_repair.py","scripts/run_real_error_budget_agent_repair.py","scripts/run_real_multiclock_agent_repair.py"}
def main():
 p=argparse.ArgumentParser();p.add_argument("summary",type=Path);a=p.parse_args();raw=json.loads(a.summary.read_text());expected=raw.pop("summary_sha256",None);actual=hashlib.sha256(json.dumps(raw,sort_keys=True,separators=(",",":")).encode()).hexdigest();steps=raw.get("steps",[]);commands=[str(part) for x in steps for part in x.get("command",[])];offline="model-setup-skipped" in commands;setup_ok=offline or "bash" in commands;results=raw.get("task_results",[]);metrics=raw.get("metrics",{});selection_observed=metrics.get("model_selection_observed_count")==sum(isinstance(x.get("model_selected_repair"),bool) for x in results);selection_complete=offline or (selection_observed and metrics.get("model_selection_observed_count")==4 and metrics.get("model_repair_selection_rate")==1.0);checks={"hash":actual==expected,"schema":raw.get("schema_version")=="real-four-causal-agent-colab-summary-v1","status":raw.get("status")=="passed","nine_steps":len(steps)==9,"all_steps_passed":all(x.get("status")=="passed" and x.get("returncode")==0 for x in steps),"model_setup":setup_ok,"task_runners":{x for x in EXPECTED if x not in commands}==set(),"four_task_results":len(results)==4 and {x.get("task") for x in results}=={"peripheral","operation","error_budget","multiclock"},"all_repairs_passed":all(x.get("status")=="passed" and x.get("baseline_failed") and x.get("causal_evidence_consumed") and x.get("repaired_passed") and x.get("canonical_unchanged") for x in results),"metrics_consistent":metrics.get("task_count")==len(results) and metrics.get("repair_success_rate")==1.0 and metrics.get("causal_evidence_consumption_rate")==1.0,"model_selection_metric":selection_observed,"model_selection_complete":selection_complete};ok=all(checks.values());print(json.dumps({"status":"passed" if ok else "failed","checks":checks},sort_keys=True));return 0 if ok else 1
